begin;
create table public.employee_invites(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),email text not null,full_name text not null,role text not null check(role in('administrador','gerente','atendente','caixa','banhista','tosador','estoquista')),commission_rate numeric(5,2) not null default 0 check(commission_rate between 0 and 100),invited_by uuid not null,accepted_at timestamptz,created_at timestamptz not null default now(),unique(company_id,email),constraint invite_user_company_fkey foreign key(invited_by,company_id) references public.profiles(id,company_id));
create index employee_invites_company_idx on public.employee_invites(company_id); create index employee_invites_inviter_idx on public.employee_invites(invited_by,company_id);
alter table public.employee_invites enable row level security;
create policy invites_select on public.employee_invites for select to authenticated using(private.has_company_role(company_id,array['proprietario','administrador']));
create policy invites_insert on public.employee_invites for insert to authenticated with check(private.has_company_role(company_id,array['proprietario','administrador']));
create policy invites_update on public.employee_invites for update to authenticated using(private.has_company_role(company_id,array['proprietario','administrador'])) with check(private.has_company_role(company_id,array['proprietario','administrador']));
grant select,insert,update on public.employee_invites to authenticated; revoke all on public.employee_invites from anon;
create policy profiles_select_invited on public.profiles for select to authenticated using(company_id is null and exists(select 1 from public.employee_invites i where lower(i.email)=lower(profiles.email) and private.has_company_role(i.company_id,array['proprietario','administrador'])));
create policy profiles_claim_invited on public.profiles for update to authenticated using(company_id is null and exists(select 1 from public.employee_invites i where lower(i.email)=lower(profiles.email) and private.has_company_role(i.company_id,array['proprietario','administrador']))) with check(private.has_company_role(company_id,array['proprietario','administrador']));
create policy commissions_update on public.commissions for update to authenticated using(private.has_company_role(company_id,array['proprietario','administrador','gerente'])) with check(private.has_company_role(company_id,array['proprietario','administrador','gerente'])); grant update on public.commissions to authenticated;
create or replace function private.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='' as $$ declare target_company uuid;first_user boolean;v_invite public.employee_invites; begin perform pg_advisory_xact_lock(8172401); select not exists(select 1 from public.profiles) into first_user; if first_user then insert into public.companies(name,trade_name,email) values('Meu Pet Shop','Meu Pet Shop',new.email) returning id into target_company; insert into public.profiles(id,company_id,full_name,email,role,is_active) values(new.id,target_company,coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),split_part(new.email,'@',1)),new.email,'proprietario',true); else select * into v_invite from public.employee_invites where lower(email)=lower(new.email) and accepted_at is null order by created_at desc limit 1; if found then insert into public.profiles(id,company_id,full_name,email,role,is_active,commission_rate) values(new.id,v_invite.company_id,v_invite.full_name,new.email,v_invite.role,true,v_invite.commission_rate); update public.employee_invites set accepted_at=now() where id=v_invite.id; else insert into public.profiles(id,company_id,full_name,email,role,is_active) values(new.id,null,coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),split_part(new.email,'@',1)),new.email,'atendente',false); end if; end if; return new; end;$$;
commit;
